(3991626, 570063, 15711, '<td valign="top">Oustanding detail. woah.</td>', 'Oustanding detail. woah.', '2007-08-13 01:06:45.000000', NULL, 1),
(3991631, 570585, 70000, '<td valign="top">To me there isn''t really much composition here, there is not focal point and having the tree right in the middle makes it a bit stagnant. exposure on the darker bushes is night but the blown out leaves take away from this in my opinion</td>', 'To me there isn''t really much composition here, there is not focal point and having the tree right in the middle makes it a bit stagnant. exposure on the darker bushes is night but the blown out leaves take away from this in my opinion', '2007-08-13 01:07:14.000000', NULL, 1),
