(3992348, 570601, 31282, '<td valign="top">I am the Lizard King, I can do anything, as Jim Morisson used to say !! Nice pic 8</td>', 'I am the Lizard King, I can do anything, as Jim Morisson used to say !! Nice pic 8', '2007-08-13 04:24:36.000000', NULL, 1),
(3992370, 569527, 66635, '<td valign="top">Thanks for the memories!  I lived in Oregon about 15 years ago and sometimes visited Sahalie Falls.  We even walked behind the water once or twice.  I sure wish I was there now.  It must be about time for the Oregon Country Fair, too.  Nice pic.</td>', 'Thanks for the memories!  I lived in Oregon about 15 years ago and sometimes visited Sahalie Falls.  We even walked behind the water once or twice.  I sure wish I was there now.  It must be about time for the Oregon Country Fair, too.  Nice pic.', '2007-08-13 04:47:27.000000', NULL, 1),
(3992374, 570618, 68956, '<td valign="top">A lovely focus on the eyes, love the high key too. :)</td>', 'A lovely focus on the eyes, love the high key too. :)', '2007-08-13 04:52:12.000000', NULL, 1),
(3992375, 569945, 52439, '<td valign="top">Stunning.</td>', 'Stunning.', '2007-08-13 04:52:14.000000', NULL, 1),
