(3992384, 569675, 53316, '<td valign="top">Wow, this totally gives me the feeling that this thing is fifty feet high and I''m looking up at it. Awesome.</td>', 'Wow, this totally gives me the feeling that this thing is fifty feet high and I''m looking up at it. Awesome.', '2007-08-13 05:11:55.000000', NULL, 1),
(3992386, 569716, 53316, '<td valign="top">I wish her face weren''t so dark. Other than that this is neat for sure. Were you trying to go for the look that she had wings? That is what it looks like to me and I really like that :-)</td>', 'I wish her face weren''t so dark. Other than that this is neat for sure. Were you trying to go for the look that she had wings? That is what it looks like to me and I really like that :-)', '2007-08-13 05:13:12.000000', NULL, 1),
(3992387, 569167, 53316, '<td valign="top">Love it!</td>', 'Love it!', '2007-08-13 05:13:22.000000', NULL, 1),
(3992391, 570224, 68956, '<td valign="top">Great sky, the highlights seem to have gone blue, but I quite like that :)</td>', 'Great sky, the highlights seem to have gone blue, but I quite like that :)', '2007-08-13 05:19:07.000000', NULL, 1),
