(3992432, 570396, 77543, '<td valign="top">Nice composition. The use of flash has caused uneven lighting. This could be fixed with a bit of dodge and burn in post production.</td>', 'Nice composition. The use of flash has caused uneven lighting. This could be fixed with a bit of dodge and burn in post production.', '2007-08-13 05:42:47.000000', NULL, 1),
(3992434, 569807, 66616, '<td valign="top">Too much out of focus for me.</td>', 'Too much out of focus for me.', '2007-08-13 05:43:06.000000', NULL, 1),
(3992436, 570460, 23251, '<td valign="top">I''m sorry but the OOF simply does not do it for me!  There is no focal point to the image so my eye''s are jumping all over the photo.</td>', 'I''m sorry but the OOF simply does not do it for me!  There is no focal point to the image so my eye''s are jumping all over the photo.', '2007-08-13 05:44:02.000000', NULL, 1),
