(3992448, 570532, 77543, '<td valign="top">A very nicely executed sunset/sunrise. I think the distortion of the wide angle lens (if that''s what you used) has created a slightly curved horizon which gives the impression it''s not straight.</td>', 'A very nicely executed sunset/sunrise. I think the distortion of the wide angle lens (if that''s what you used) has created a slightly curved horizon which gives the impression it''s not straight.', '2007-08-13 05:49:09.000000', NULL, 1),
(3992449, 570379, 34938, '<td valign="top">wow...looks like an alien landscape...great landscape, pineapples beat grass :-)</td>', 'wow...looks like an alien landscape...great landscape, pineapples beat grass :-)', '2007-08-13 05:49:39.000000', NULL, 1),
(3992450, 569364, 73957, '<td valign="top">sorry for the bird, and the composition could be improved (empty space on top)</td>', 'sorry for the bird, and the composition could be improved (empty space on top)', '2007-08-13 05:49:53.000000', NULL, 1),
(3992451, 570271, 66616, '<td valign="top">no real focus point for the eye.</td>', 'no real focus point for the eye.', '2007-08-13 05:49:59.000000', NULL, 1),
