(3992460, 570067, 66616, '<td valign="top">I feel that the middle background is to dark for the rest of this image.</td>', 'I feel that the middle background is to dark for the rest of this image.', '2007-08-13 05:53:47.000000', NULL, 1),
(3992463, 569232, 77543, '<td valign="top">I like the low angle. If the vertical bar in the background was either missing or directly behind the head this would have been much better.</td>', 'I like the low angle. If the vertical bar in the background was either missing or directly behind the head this would have been much better.', '2007-08-13 05:54:53.000000', NULL, 1),
(3992465, 570274, 66616, '<td valign="top">Too light.</td>', 'Too light.', '2007-08-13 05:55:24.000000', NULL, 1),
(3992466, 570539, 66616, '<td valign="top">?</td>', '?', '2007-08-13 05:55:43.000000', NULL, 1),
(3992469, 570330, 66616, '<td valign="top">Very sharp but composition could be better.</td>', 'Very sharp but composition could be better.', '2007-08-13 05:56:29.000000', NULL, 1),
(3992470, 570137, 34938, '<td valign="top">great macro image...this would make it in a magazine...excellent 9</td>', 'great macro image...this would make it in a magazine...excellent 9', '2007-08-13 05:56:50.000000', NULL, 1),
(3992471, 570379, 66616, '<td valign="top">Not enough contrast for my liking. But the more I look at it the more I like it.<br/><br/><i>Message edited by author 2007-08-21 04:27:10.</i></td>', 'Not enough contrast for my liking. But the more I look at it the more I like it.', '2007-08-13 05:57:16.000000', '2007-08-21 05:27:10.000000', 1),
(3992473, 570384, 77543, '<td valign="top">There is very little detail in the shadows. The brightness of the tree tops and sky make it impossible to get a good picture without post processing.</td>', 'There is very little detail in the shadows. The brightness of the tree tops and sky make it impossible to get a good picture without post processing.', '2007-08-13 05:58:48.000000', NULL, 1),
(3992481, 570051, 34938, '<td valign="top">perfect! one of the best ''drop'' images around...the reflection is superb as is the shape 10 from me...congrats on the ribbon in advance</td>', 'perfect! one of the best ''drop'' images around...the reflection is superb as is the shape 10 from me...congrats on the ribbon in advance', '2007-08-13 06:03:20.000000', NULL, 1),
(3992483, 570355, 77543, '<td valign="top">You don''t see one of those every day.<br/>The background and sky seem a little flat but that might have been intentional. I think the boat is too centred - apply the rule of thirds.</td>', 'You don''t see one of those every day.The background and sky seem a little flat but that might have been intentional. I think the boat is too centred - apply the rule of thirds.', '2007-08-13 06:04:15.000000', NULL, 1),
