(3992487, 570605, 34938, '<td valign="top">beautiful depth in the sky...</td>', 'beautiful depth in the sky...', '2007-08-13 06:05:04.000000', NULL, 1),
(3992491, 570330, 34938, '<td valign="top">nice colour and light</td>', 'nice colour and light', '2007-08-13 06:05:36.000000', NULL, 1),
