(3992495, 569782, 34938, '<td valign="top">great detail and colour</td>', 'great detail and colour', '2007-08-13 06:05:58.000000', NULL, 1),
(3992496, 569923, 34938, '<td valign="top">lovely study...makes a great abstract 9</td>', 'lovely study...makes a great abstract 9', '2007-08-13 06:06:23.000000', NULL, 1),
