INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4005085, 569906, 9906, '<td valign="top">Very cute shot!  This could easily have looked like a snapshot but this is very well done!  Kudos<br/>TC</td>', 'Very cute shot!  This could easily have looked like a snapshot but this is very well done!  KudosTC', '2007-08-16 19:05:53.000000', NULL, 1),
(4005087, 570168, 9906, '<td valign="top">Did you use HDR on this?  Your colors are incredible!<br/>TC</td>', 'Did you use HDR on this?  Your colors are incredible!TC', '2007-08-16 19:06:45.000000', NULL, 1),
(4005133, 570366, 69325, '<td valign="top">TOO MUCH POST PROCESSING! but i still like the juxtaposition (ya like that big word?) of the b&amp;w and color /8</td>', 'TOO MUCH POST PROCESSING! but i still like the juxtaposition (ya like that big word?) of the b&w and color /8', '2007-08-16 19:32:01.000000', NULL, 1),
(4005135, 570703, 9906, '<td valign="top">This looks to be really underexposed as you lost much of the detail in the greenery...<br/>TC</td>', 'This looks to be really underexposed as you lost much of the detail in the greenery...TC', '2007-08-16 19:33:00.000000', NULL, 1),
(4005140, 570666, 9906, '<td valign="top">Excellent!  I love to take pics of flowers and turn them b/w.  It brings out all the texture in the flower that you normally don''t really <i>see</i> because the color kind of obscures it...<br/>kudos<br/>TC</td>', 'Excellent!  I love to take pics of flowers and turn them b/w.  It brings out all the texture in the flower that you normally don''t really see because the color kind of obscures it...kudosTC', '2007-08-16 19:34:20.000000', NULL, 1),
(4005142, 570363, 9906, '<td valign="top">Looks to be a little bit oof as nothing seems to be truly sharp...<br/>TC</td>', 'Looks to be a little bit oof as nothing seems to be truly sharp...TC', '2007-08-16 19:35:14.000000', NULL, 1),
(4005147, 569355, 9906, '<td valign="top">A touch more exposure and this would be the bomb!  Re-shoot time!<br/>TC</td>', 'A touch more exposure and this would be the bomb!  Re-shoot time!TC', '2007-08-16 19:36:13.000000', NULL, 1),
