(4005216, 569330, 9906, '<td valign="top">What a nice study in lighting!<br/>TC</td>', 'What a nice study in lighting!TC', '2007-08-16 20:18:50.000000', NULL, 1),
(4005222, 570119, 9906, '<td valign="top">For some reason your blurred background doesn''t look <i>right</i>.  Kinda like it was photoshopped in.  Doesn''t mean it was but it looks that way for some reason.  Over all a nice shot of a nice car!<br/>TC</td>', 'For some reason your blurred background doesn''t look right.  Kinda like it was photoshopped in.  Doesn''t mean it was but it looks that way for some reason.  Over all a nice shot of a nice car!TC', '2007-08-16 20:23:32.000000', NULL, 1),
