(4011311, 570207, 9906, '<td valign="top">Nice capture.  It''s not too often that you see a shot that has no subject that can actually hold your attention.<br/>TC</td>', 'Nice capture.  It''s not too often that you see a shot that has no subject that can actually hold your attention.TC', '2007-08-19 15:54:34.000000', NULL, 1),
