(4014414, 569814, 11769, '<td valign="top">Congrats on the ribbon Sandy! Exquisite, powerful image. Very well done.</td>', 'Congrats on the ribbon Sandy! Exquisite, powerful image. Very well done.', '2007-08-20 13:06:16.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4014419, 570054, 44877, '<td valign="top">I thought it was a turkey accident by the thumb - haha!!</td>', 'I thought it was a turkey accident by the thumb - haha!!', '2007-08-20 13:08:54.000000', NULL, 0),
(4014435, 570274, 51269, '<td valign="top">Everybody has an opinion-mine is: this is gorgeous ! The title is perfect for that feline stare.</td>', 'Everybody has an opinion-mine is: this is gorgeous ! The title is perfect for that feline stare.', '2007-08-20 13:12:40.000000', NULL, 0),
(4014441, 570195, 52549, '<td valign="top">I really like this a lot. It''s beautifully crisp and clean and a great idea (must try it sometime). Congrats on top 10, Darren.</td>', 'I really like this a lot. It''s beautifully crisp and clean and a great idea (must try it sometime). Congrats on top 10, Darren.', '2007-08-20 13:13:15.000000', NULL, 0),
(4014452, 570285, 51269, '<td valign="top">Excellent capture !</td>', 'Excellent capture !', '2007-08-20 13:16:57.000000', NULL, 0),
(4014458, 570246, 52549, '<td valign="top">This is lovely, very fragile looking - the pink gives it a very serene look, almost transcendental.</td>', 'This is lovely, very fragile looking - the pink gives it a very serene look, almost transcendental.', '2007-08-20 13:18:46.000000', NULL, 0),
(4014502, 570701, 75162, '<td valign="top">LOVE IT!!<br/>the blur ,the natural pose and the sincere smile makes it a REAL photograph. That''s all photography is about, for me!<br/> <br/>tanks!</td>', 'LOVE IT!!the blur ,the natural pose and the sincere smile makes it a REAL photograph. That''s all photography is about, for me! tanks!', '2007-08-20 13:24:25.000000', NULL, 0),
(4014516, 570238, 51269, '<td valign="top">Very nice job- beautiful image. (I almost always use 4-5.6 on my macro for florals)</td>', 'Very nice job- beautiful image. (I almost always use 4-5.6 on my macro for florals)', '2007-08-20 13:28:04.000000', NULL, 0),
(4014543, 569521, 37529, '<td valign="top">I thought your photo would do alot better than it did, top ten at least I figured.  I really like the creativity, focus, and overall concept. I am curious what your process was in setting up this shot. Can you share?</td>', 'I thought your photo would do alot better than it did, top ten at least I figured.  I really like the creativity, focus, and overall concept. I am curious what your process was in setting up this shot. Can you share?', '2007-08-20 13:34:20.000000', NULL, 0),
(4014553, 570537, 37529, '<td valign="top">I agree, way underrated.  I gave it a 9.  Beautiful portrait of your sister.</td>', 'I agree, way underrated.  I gave it a 9.  Beautiful portrait of your sister.', '2007-08-20 13:39:08.000000', NULL, 0),
(4014567, 569922, 42100, '<td valign="top">I''ve been around long enough now to know that this wasn''t going to finish near the top(a real shame there is such a bias)...but, I wanted to let you know I really appreciated and enjoyed this photo!  I look forward to seeing more.<br/><br/><i>Message edited by author 2007-08-20 12:43:31.</i></td>', 'I''ve been around long enough now to know that this wasn''t going to finish near the top(a real shame there is such a bias)...but, I wanted to let you know I really appreciated and enjoyed this photo!  I look forward to seeing more.', '2007-08-20 13:42:40.000000', '2007-08-20 13:43:31.000000', 0),
(4014600, 569814, 65319, '<td valign="top">Congratulations on your ribbon!!!!  I''m thrilled for you!  Well done.</td>', 'Congratulations on your ribbon!!!!  I''m thrilled for you!  Well done.', '2007-08-20 13:55:44.000000', NULL, 0),
(4014626, 570051, 52115, '<td valign="top">Wow, you just keep dropping in on them ribbons with your dropped shots. Is this your 4th ribbonmaker out of drops. Where can I see the Drops Gallery on tour?</td>', 'Wow, you just keep dropping in on them ribbons with your dropped shots. Is this your 4th ribbonmaker out of drops. Where can I see the Drops Gallery on tour?', '2007-08-20 14:04:16.000000', NULL, 0),
(4014645, 570051, 11518, '<td valign="top">Well deserved blue.  Ignore the jealous naysayers, good drop shots are hard to consistently produce, it takes a lot of time and dedication.  Kudos.</td>', 'Well deserved blue.  Ignore the jealous naysayers, good drop shots are hard to consistently produce, it takes a lot of time and dedication.  Kudos.', '2007-08-20 14:11:56.000000', NULL, 0),
(4014658, 570051, 52549, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by doctornick:</b></div><hr/><i> Well deserved blue.  Ignore the jealous naysayers, good drop shots are hard to consistently produce, it takes a lot of time and dedication.  Kudos. </i></td></tr></table> <br/> <br/>Thanks, Nick!<br/>And thanks to everyone for the great post challenge comments. You''ve made my day.</td>', 'Originally posted by doctornick: Well deserved blue.  Ignore the jealous naysayers, good drop shots are hard to consistently produce, it takes a lot of time and dedication.  Kudos.   Thanks, Nick!And thanks to everyone for the great post challenge comments. You''ve made my day.', '2007-08-20 14:17:55.000000', NULL, 0),
(4014667, 569877, 30982, '<td valign="top">Quite clever and intriguing.  Reminds me of some children''s thing that would create interesting designs but I''ll be darned if I know what that was.  And I''m betting there''s some equation that would describe the pattern, but I''ll be darned if I could figure that out these days either.  Your picture makes me feel old.  :-)</td>', 'Quite clever and intriguing.  Reminds me of some children''s thing that would create interesting designs but I''ll be darned if I know what that was.  And I''m betting there''s some equation that would describe the pattern, but I''ll be darned if I could figure that out these days either.  Your picture makes me feel old.  :-)', '2007-08-20 14:26:56.000000', NULL, 0),
(4014669, 570238, 30982, '<td valign="top">Nice comment from Don, and I agree that it looks like a projection of the flower - what it wants to be when it grows up, kinda.  Gorgeous softness and very nice use of DOF.</td>', 'Nice comment from Don, and I agree that it looks like a projection of the flower - what it wants to be when it grows up, kinda.  Gorgeous softness and very nice use of DOF.', '2007-08-20 14:28:32.000000', NULL, 0),
(4014675, 569805, 30982, '<td valign="top">First, congrats on the ribbon!  Those aren''t as easy to get as most folks think.  :-)  Next, I have no idea why this scored where it did.  The title is just a bit misleading - she''s alone on the beach but she''s being watched over by the kite aloft.  At least that''s how I see it.  It''s well composed, and well balanced to me despite the horizon not being on the blessed rule of thirds line.  To crop it so would cramp the kite.</td>', 'First, congrats on the ribbon!  Those aren''t as easy to get as most folks think.  :-)  Next, I have no idea why this scored where it did.  The title is just a bit misleading - she''s alone on the beach but she''s being watched over by the kite aloft.  At least that''s how I see it.  It''s well composed, and well balanced to me despite the horizon not being on the blessed rule of thirds line.  To crop it so would cramp the kite.', '2007-08-20 14:31:33.000000', NULL, 0),
(4014680, 569814, 50578, '<td valign="top">Very nice shot.  Amazing how the perspective changes when you see her smiling in the other photo.   She looks like a model  apart from the aged skin.  Probably was very nice looking in her day.</td>', 'Very nice shot.  Amazing how the perspective changes when you see her smiling in the other photo.   She looks like a model  apart from the aged skin.  Probably was very nice looking in her day.', '2007-08-20 14:33:52.000000', NULL, 0),
(4014682, 570534, 30982, '<td valign="top">This was one I did get to in voting, and I swear I thought I left a comment... apparently I did not, but had I done so I can assure you the commenter average would be much higher.  I did indeed get the All American references and thought the sepia, grain, and even the brightness of it very well suited to the photo.</td>', 'This was one I did get to in voting, and I swear I thought I left a comment... apparently I did not, but had I done so I can assure you the commenter average would be much higher.  I did indeed get the All American references and thought the sepia, grain, and even the brightness of it very well suited to the photo.', '2007-08-20 14:35:12.000000', NULL, 0),
(4014683, 570120, 52169, '<td valign="top">I loved this image. I did a whole series of paintings that used birdcages as a metaphor. I love your work.</td>', 'I loved this image. I did a whole series of paintings that used birdcages as a metaphor. I love your work.', '2007-08-20 14:37:28.000000', NULL, 0),
(4014688, 569656, 30982, '<td valign="top">I didn''t notice that the top was distracting until you pointed it out, and even now it doesn''t bother me.  It in fact provides a good sense of scale.  I did click on this one during the challenge - I quite liked the curves, both solid and soft, and her outfit made for a very nice color balance to the shot.</td>', 'I didn''t notice that the top was distracting until you pointed it out, and even now it doesn''t bother me.  It in fact provides a good sense of scale.  I did click on this one during the challenge - I quite liked the curves, both solid and soft, and her outfit made for a very nice color balance to the shot.', '2007-08-20 14:38:00.000000', NULL, 0),
(4014697, 570324, 30982, '<td valign="top">A mystery and a sense of loss.  There''s the obvious openness inviting us in, but the lack of a place to go creates a dilemma.  But can we just walk away?  And I like the textures.  :-)</td>', 'A mystery and a sense of loss.  There''s the obvious openness inviting us in, but the lack of a place to go creates a dilemma.  But can we just walk away?  And I like the textures.  :-)', '2007-08-20 14:41:07.000000', NULL, 0),
(4014709, 570244, 30982, '<td valign="top">Half the appeal of this is the tension created even though it''s stopped motion - the hands are just above the ground - one is waiting for them to touch.  The other half is the wonder of the human form - the shape created by the young man is a fascination unto itself.</td>', 'Half the appeal of this is the tension created even though it''s stopped motion - the hands are just above the ground - one is waiting for them to touch.  The other half is the wonder of the human form - the shape created by the young man is a fascination unto itself.', '2007-08-20 14:47:29.000000', NULL, 0),
(4014710, 570238, 62318, '<td valign="top">Love the complimentary colors. You could have used this for backlighting. Nice effect. Congrats on the high placement on such a large field.</td>', 'Love the complimentary colors. You could have used this for backlighting. Nice effect. Congrats on the high placement on such a large field.', '2007-08-20 14:47:45.000000', NULL, 0),
(4014712, 570244, 62318, '<td valign="top">Outside or inside? I''ve tried to shoot gymnastics before and know how difficult it can be. This is a terrific capture. Terrific depth and frozen action with wonderful colors. Congrats on the nice placement in the large field.</td>', 'Outside or inside? I''ve tried to shoot gymnastics before and know how difficult it can be. This is a terrific capture. Terrific depth and frozen action with wonderful colors. Congrats on the nice placement in the large field.', '2007-08-20 14:49:05.000000', NULL, 0),
(4014715, 570355, 62318, '<td valign="top">Very cool shot. I think if you would have added a bit more contrast in the top section your probably would have scored a full point higher. Still, I think it is terrific as is and the square frame works well here. Cheers.</td>', 'Very cool shot. I think if you would have added a bit more contrast in the top section your probably would have scored a full point higher. Still, I think it is terrific as is and the square frame works well here. Cheers.', '2007-08-20 14:50:33.000000', NULL, 0),
(4014716, 570355, 30982, '<td valign="top">I beg to differ with some of the other commenters - I quite like the boat centered and in fact think it suits this very well.  I think, though, that I''d like to see the background even duller/flatter as far as color is concerned, while maintaining the vibrance of the boat, to even further enhance the mystical time/space unreality.</td>', 'I beg to differ with some of the other commenters - I quite like the boat centered and in fact think it suits this very well.  I think, though, that I''d like to see the background even duller/flatter as far as color is concerned, while maintaining the vibrance of the boat, to even further enhance the mystical time/space unreality.', '2007-08-20 14:50:47.000000', NULL, 0),
(4014717, 570051, 31403, '<td valign="top">:-)</td>', ':-)', '2007-08-20 14:51:04.000000', NULL, 0),
