INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6215585, 570246, 114285, '<td valign="top">Great pp, love the colours.</td>', 'Great pp, love the colours.', '2010-11-07 22:22:26.000000', NULL, 0),
(6220563, 570405, 114285, '<td valign="top">Totally brilliant.</td>', 'Totally brilliant.', '2010-11-11 22:57:42.000000', NULL, 0),
(6362970, 569814, 772, '<td valign="top">This is an excellent character portrait for sure :)  I love photographing people much in the way you have done here, and early in my decision to pursue that avenue, I had to deal with the issue of photographer ''fear'' of people.  It seems to me that most photographers I know are too afraid or shy to speak with a stranger and simply ask them if you may make a few photos.  Most seem to want to take that candid stealth route.  For the last several years, I have been working on a "1000 Faces" series of photographs.  I''m a long way from finishing it, but each person in the series is someone I have interacted with in one way or another.  Some are candid and some are impromptu portraits on location.  But each of them are of a person who I have had some amount of verbal dialogue with... there are even a few celebrities.  It really is amazing how you can briefly get to know someone and maybe even learn something by simply talking to them.  I most often find my subject and start a conversation before I ask for the photographs and I''m rarely turned down.  <br/> <br/>This is a worthy pursuit :)</td>', 'This is an excellent character portrait for sure :)  I love photographing people much in the way you have done here, and early in my decision to pursue that avenue, I had to deal with the issue of photographer ''fear'' of people.  It seems to me that most photographers I know are too afraid or shy to speak with a stranger and simply ask them if you may make a few photos.  Most seem to want to take that candid stealth route.  For the last several years, I have been working on a "1000 Faces" series of photographs.  I''m a long way from finishing it, but each person in the series is someone I have interacted with in one way or another.  Some are candid and some are impromptu portraits on location.  But each of them are of a person who I have had some amount of verbal dialogue with... there are even a few celebrities.  It really is amazing how you can briefly get to know someone and maybe even learn something by simply talking to them.  I most often find my subject and start a conversation before I ask for the photographs and I''m rarely turned down.   This is a worthy pursuit :)', '2011-03-24 21:48:12.000000', NULL, 0),
(6426565, 570530, 68504, '<td valign="top">Very pleasing, helped by the benevolent seeming "face."</td>', 'Very pleasing, helped by the benevolent seeming "face."', '2011-05-28 02:49:03.000000', NULL, 0),
(6502695, 570496, 68504, '<td valign="top">and this is such a fine goodbye pic for pooch.</td>', 'and this is such a fine goodbye pic for pooch.', '2011-08-12 12:34:24.000000', NULL, 0),
(6502715, 570496, 96751, '<td valign="top">Sad to hear of this poor pup''s demise.</td>', 'Sad to hear of this poor pup''s demise.', '2011-08-12 13:14:20.000000', NULL, 0),
(6502875, 570496, 554, '<td valign="top">A favorite, in memory of the dog.</td>', 'A favorite, in memory of the dog.', '2011-08-12 16:35:20.000000', NULL, 0),
(6599776, 570571, 95412, '<td valign="top">Just LOVED the title!</td>', 'Just LOVED the title!', '2011-11-21 06:56:36.000000', NULL, 0),
(6637949, 570438, 49018, '<td valign="top">Wonderful..</td>', 'Wonderful..', '2012-01-07 20:20:02.000000', NULL, 0),
(6814183, 570051, 150487, '<td valign="top">wonderfully executed shot</td>', 'wonderfully executed shot', '2012-07-10 07:52:39.000000', NULL, 0),
(6839636, 569814, 135629, '<td valign="top">Lisa looks like she is one of the actual untouchables. There are few among us that dance over the threats of cancer from smoking, complications of old age, etc... and just turn in to bad ass old folks that live long to tell many tales. I imagine she is blessed with that curse. SHe probably has as many interesting stories as she does wrinkles, and an equal amount of tragedy to bestow on whomever may lend an ear. I could be way off base, but that''s what I think when I see this photo, and I think a photo that makes me think that much... is great :) Great work.</td>', 'Lisa looks like she is one of the actual untouchables. There are few among us that dance over the threats of cancer from smoking, complications of old age, etc... and just turn in to bad ass old folks that live long to tell many tales. I imagine she is blessed with that curse. SHe probably has as many interesting stories as she does wrinkles, and an equal amount of tragedy to bestow on whomever may lend an ear. I could be way off base, but that''s what I think when I see this photo, and I think a photo that makes me think that much... is great :) Great work.', '2012-08-10 23:49:21.000000', NULL, 0),
(6918083, 569204, 5112, '<td valign="top">Never would have thought of making a long exposure of a disco ball.  What an idea!  Amazing how you got the edges sharp (no wobbles).  I like it overall.  I especially like the striping that happened from the reflections on the mirrors.  Very nice.</td>', 'Never would have thought of making a long exposure of a disco ball.  What an idea!  Amazing how you got the edges sharp (no wobbles).  I like it overall.  I especially like the striping that happened from the reflections on the mirrors.  Very nice.', '2012-12-01 11:10:02.000000', NULL, 0),
(6980275, 569814, 96574, '<td valign="top">this has long been one of my favorite pictures from the site. so much character in her face. simply an amazing shot.</td>', 'this has long been one of my favorite pictures from the site. so much character in her face. simply an amazing shot.', '2013-02-16 14:27:01.000000', NULL, 0),
(7078819, 569814, 152252, '<td valign="top">That''s a beautiful portrait. It says it all. Best example that a picture is worth a thousand words.<br/><br/><i>Message edited by author 2013-07-30 15:17:08.</i></td>', 'That''s a beautiful portrait. It says it all. Best example that a picture is worth a thousand words.', '2013-07-30 16:16:51.000000', '2013-07-30 16:17:08.000000', 0),
